 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    patterns = []
    # Any horizontal run of two or more nonzero cells is a pattern template.
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start >= 2:
                patterns.append(row[start:c])
    # Singleton colored markers are replaced by the full pattern containing
    # that color, aligned so the matching pattern cell remains on the marker.
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start != 1:
                continue
            color = row[start]
            for pattern in patterns:
                if color in pattern:
                    offset = pattern.index(color)
                    left = start - offset
                    for j, value in enumerate(pattern):
                        x = left + j
                        if 0 <= x < w:
                            out[r][x] = value
                    break
    return out
